/**
 * Boolean (or indeterminate) choice (`design/components/checkbox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/checkbox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/checkbox'
import { normalizeProps } from '@zag-js/solid'

import {
  Icon,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  scope,
  useDirection,
  useMachine,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/checkbox.module.css'

export type CheckedState = boolean | 'indeterminate'

export interface CheckboxProps {
  'aria-describedby'?: string
  'aria-label'?: string
  /**
   * The id of a label elsewhere on the page, such as `SettingsRow`'s one label for a whole row.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  checked?: boolean | 'indeterminate'
  defaultChecked?: boolean | 'indeterminate'
  disabled?: boolean
  id?: string
  /**
   * Usually set by FormField.
   */
  invalid?: boolean
  /**
   * Visible inline label. Omit it only where the context labels the box, and then `aria-label`
   * is required.
   */
  label?: string
  name?: string
  onCheckedChange?: (checked: CheckedState) => void
  value?: string
}

/** Boolean (or indeterminate) choice. */
export default function Checkbox(given: CheckboxProps): JSX.Element {
  const props = mergeProps(
    { disabled: false, invalid: false } as Defaults<CheckboxProps, 'disabled' | 'invalid'>,
    claimSlot(given, 'row-labelled'),
  )
  return scope(() => {
    const uid = createUniqueId()
    const box = elementRef<HTMLElement>()
    const documentDirection = useDirection(() => box.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          checked: props.checked,
          defaultChecked: props.defaultChecked,
          disabled: props.disabled,
          invalid: props.invalid,
          required: props['aria-required'],
          name: props.name,
          value: props.value,
          onCheckedChange: (details) => {
            props.onCheckedChange?.(details.checked)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const dataState = createDerived(() =>
      api.value.indeterminate ? 'indeterminate' : api.value.checked ? 'checked' : 'unchecked',
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'Checkbox',
        element: () => box.value,
        state: () => ({
          checked: api.value.indeterminate ? 'mixed' : api.value.checked,
          disabled: props.disabled,
        }),
        actions: {
          check: () => api.value.setChecked(true),
          uncheck: () => api.value.setChecked(false),
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <>
        {props.label === undefined ? (
          <button
            class={styles.box}
            type="button"
            role="checkbox"
            id={props.id}
            aria-checked={api.value.indeterminate ? 'mixed' : api.value.checked}
            disabled={props.disabled}
            aria-label={props['aria-label']}
            aria-labelledby={props['aria-labelledby']}
            aria-describedby={props['aria-describedby']}
            aria-required={props['aria-required']}
            aria-invalid={props.invalid ? true : undefined}
            data-state={dataState.value}
            data-disabled={props.disabled ? '' : undefined}
            data-required={props['aria-required'] ? '' : undefined}
            data-invalid={props.invalid ? '' : undefined}
            data-member="checkbox"
            onclick={() => api.value.toggleChecked()}
            onkeydown={($event: KeyboardEvent) => $event.key === 'Enter' && $event.preventDefault()}
            ref={box.attach}
          >
            {api.value.checked || api.value.indeterminate ? (
              <span class={styles.indicator} data-state={dataState.value}>
                <Icon name={api.value.indeterminate ? 'indeterminate' : 'confirm'} size="sm" />
              </span>
            ) : null}
          </button>
        ) : (
          <label
            class={styles.row}
            data-state={dataState.value}
            data-disabled={props.disabled ? '' : undefined}
            data-invalid={props.invalid ? '' : undefined}
            data-required={props['aria-required'] ? '' : undefined}
            data-member="checkbox"
          >
            {/* box */}
            <button
              class={styles.box}
              type="button"
              role="checkbox"
              id={props.id}
              aria-checked={api.value.indeterminate ? 'mixed' : api.value.checked}
              disabled={props.disabled}
              aria-label={props['aria-label']}
              aria-labelledby={props['aria-labelledby']}
              aria-describedby={props['aria-describedby']}
              aria-required={props['aria-required']}
              aria-invalid={props.invalid ? true : undefined}
              data-state={dataState.value}
              data-disabled={props.disabled ? '' : undefined}
              data-required={props['aria-required'] ? '' : undefined}
              data-invalid={props.invalid ? '' : undefined}
              data-member="checkbox"
              onclick={() => api.value.toggleChecked()}
              onkeydown={($event: KeyboardEvent) =>
                $event.key === 'Enter' && $event.preventDefault()
              }
              ref={box.attach}
            >
              {api.value.checked || api.value.indeterminate ? (
                <span class={styles.indicator} data-state={dataState.value}>
                  <Icon name={api.value.indeterminate ? 'indeterminate' : 'confirm'} size="sm" />
                </span>
              ) : null}
            </button>
            {/* label */}
            <span class={styles.label}>{props.label}</span>
          </label>
        )}
        {props.name !== undefined && api.value.checked ? (
          <input type="hidden" name={props.name} value={props.value ?? 'on'} />
        ) : null}
      </>
    )
  })
}

Checkbox.controlKind = 'row-labelled'
